int
ex_poly_candidate(struct monst *mon)
{
    int i, total = 0, selected = NON_PM, weight;
    const struct permonst *old = mon->data, *pm;
    if (ex_protected_monster(mon) || (old->geno & G_UNIQ)) return NON_PM;
    /* Weighted reservoir over a finite legal native form pool. */
    for (i = LOW_PM; i < SPECIAL_PM; ++i) {
        pm = &mons[i];
        weight = pm->geno & G_FREQ;
        if (pm == old || !weight || !polyok(pm) || is_placeholder(pm)
            || (pm->geno & (G_UNIQ | G_NOGEN))
            || (svm.mvitals[i].mvflags & (G_GENOD | G_EXTINCT))
            || pm->mlevel > old->mlevel || pm->difficulty > old->difficulty
            || ((pm->geno & G_HELL) && !In_hell(&u.uz))
            || ((pm->geno & G_NOHELL) && In_hell(&u.uz))) continue;
        total += weight;
        if (rn2(total) < weight) selected = i;
    }
    return selected;
}

static int
ex_loot_eligible(struct obj *obj)
{
    struct obj *nested;
    if (ex_protected_object(obj) || (obj->cursed && obj->owornmask)) return 0;
    for (nested = obj->cobj; nested; nested = nested->nobj)
        if (!ex_loot_eligible(nested)) return 0;
    return 1;
}

void
ex_steal(struct monst *mon)
{
    struct obj *obj, *chosen = 0;
    int n = 0, burden, nomerge;
    long worn;
    for (obj = mon->minvent; obj; obj = obj->nobj)
        if (ex_loot_eligible(obj) && !rn2(++n)) chosen = obj;
    if (!chosen) return;
    burden = calc_capacity((int) chosen->owt);
    worn = chosen->owornmask;
    nomerge = chosen->nomerge;
    chosen->nomerge = 1; /* The selected entire stack keeps its own identity. */
    extract_from_minvent(mon, chosen, TRUE, FALSE);
    if (burden > near_capacity()) {
        if (!flooreffects(chosen, u.ux, u.uy, "fall")) {
            place_object(chosen, u.ux, u.uy);
            stackobj(chosen);
            chosen->nomerge = nomerge;
            newsym(u.ux, u.uy);
        }
    } else {
        chosen = hold_another_object(chosen, "You snatch but drop %s.",
                                     doname(chosen), "You steal: ");
        if (chosen) chosen->nomerge = nomerge;
        if (chosen && chosen->where == OBJ_INVENT && !uarmg
            && chosen->otyp == CORPSE && !Stone_resistance
            && touch_petrifies(&mons[chosen->corpsenm]))
            instapetrify(corpse_xname(chosen, "stolen", CXN_ARTICLE));
    }
    if (worn & W_WEP) possibly_unwield(mon, FALSE);
    if ((worn & W_ARMG) && !DEADMONSTER(mon)) mselftouch(mon, (const char *) 0, TRUE);
}

void
ex_hit_begin(struct ex_hit_context *ctx, struct monst *mon, struct obj *weapon,
             const struct attack *attack)
{
    unsigned i;
    struct obj *source;
    int elements[4], n, element, base;
    boolean oldapplies;
    memset(ctx, 0, sizeof *ctx);
    ctx->target = mon->m_id;
    ctx->weapon = weapon ? weapon->o_id : 0;
    if (weapon) {
        ctx->strike = *weapon;
        ctx->strike.oextra = NULL;
        ctx->has_strike = 1;
    }
    ctx->twohits = gt.twohits;
    ctx->two_weapon = u.twoweap && weapon && (weapon == uwep || weapon == uswapwep);
    ctx->main_hand = weapon && weapon == uwep && !u.twoweap;
    ctx->thrown = HMON_MELEE;
    ctx->native_bonus = 1;
    ctx->native_skill = weapon != NULL;
    ctx->x = mon->mx; ctx->y = mon->my; ctx->oldhp = mon->mhp;
    ctx->attack = *attack;
    ex_contact_id = mon->m_id;
    ex_contact_data = mon->data;
    ex_contact_mcan = mon->mcan;
    ex_contact_mlevel = mon->m_lev;
    ex_contact_cansee = mon->mcansee;
    ex_contact_ability = mon->ex_mute_ability;
    ex_contact_suppressed = mon->ex_mute_until > svm.moves
        && mon->ex_mute_species == monsndx(mon->data);
    ex_contact_pending = 1;
    ctx->enabled = !ex_secondary();
    ex_cancel_element();
    if (!ctx->enabled) return;
    ex_snapshot(&ctx->sources, &gy.youmonst);
    for (i = 0; i < ctx->sources.count; ++i) {
        source = ex_source(&ctx->sources, i, EX_FRENZY, &gy.youmonst);
        if (source && (!(source->exotic.striking & (1UL << EX_FRENZY))
                       || source->o_id == ctx->weapon)) {
            ctx->defer_primary = 1;
            break;
        }
    }
    if (ctx->defer_primary && weapon && weapon->oartifact
        && (attacks(AD_FIRE, weapon) || attacks(AD_COLD, weapon)
            || attacks(AD_ELEC, weapon) || attacks(AD_ACID, weapon))) {
        ex_element_pending.enabled = 1;
        ex_element_pending.target = mon->m_id;
        ex_element_pending.weapon = weapon->o_id;
    }
    for (i = 0; i < ctx->sources.count; ++i) {
        source = ex_source(&ctx->sources, i, EX_CHAIN, &gy.youmonst);
        /* Only the actual intrinsic native artifact resolver is eligible.
         * Forge elements and unrelated carried elemental artifacts are not. */
        if (!source || !source->oartifact
            || (source != weapon && !source->exotic.chain_native)) continue;
        n = 0;
        if (attacks(AD_FIRE, source)) elements[n++] = AD_FIRE;
        if (attacks(AD_COLD, source)) elements[n++] = AD_COLD;
        if (attacks(AD_ELEC, source)) elements[n++] = AD_ELEC;
        if (attacks(AD_ACID, source)) elements[n++] = AD_ACID;
        if (!n || !ex_combat_chance(30)) continue;
        element = elements[rn2(n)];
        oldapplies = gs.spec_dbon_applies;
        base = spec_dbon(source, mon, max(1, dmgval(source, mon)));
        gs.spec_dbon_applies = oldapplies;
        if (base > 0) {
            ctx->chain[ctx->chains].element = element;
            ctx->chain[ctx->chains++].base = base;
        }
    }
}

static int
ex_fresh_physical(struct ex_hit_context *ctx, struct monst *mon)
{
    return ex_native_physical_roll(ctx, mon);
}

int
ex_hit_frenzy(struct ex_hit_context *ctx, struct monst *mon, int physical)
{
    unsigned i;
    int tick, total = 0, dmg;
    if (!ctx->enabled || physical <= 0 || DEADMONSTER(mon)) return 0;
    if (ctx->has_strike && (ctx->strike.otyp == ACID_VENOM
        || ctx->strike.otyp == BLINDING_VENOM || ctx->strike.otyp == CREAM_PIE))
        return 0;
    for (i = 0; i < ctx->sources.count; ++i) {
        struct obj *source = ex_source(&ctx->sources, i, EX_FRENZY, &gy.youmonst);
        if (!source || ((source->exotic.striking & (1UL << EX_FRENZY))
                        && source->o_id != ctx->weapon) || !ex_combat_chance(20)) continue;
        for (tick = 0; tick < 3; ++tick) {
            dmg = ex_fresh_physical(ctx, mon);
            dmg = enhancement_reduce(mon, dmg, ENH_PHYSICAL);
            total += min(mon->mhp, dmg);
            mon->mhp -= dmg;
            if (DEADMONSTER(mon)) {
                ctx->death_processed = 1;
                killed(mon);
            }
            if (DEADMONSTER(mon) || !mon->mx || tick == 2 || !ex_combat_chance(45)) break;
        }
        if (DEADMONSTER(mon) || !mon->mx) break;
    }
    ctx->actual_damage += total;
    return total;
}

static int
ex_chain_open(int x, int y)
{
    return isok(x, y) && !IS_STWALL(levl[x][y].typ)
           && !(IS_DOOR(levl[x][y].typ)
                && (levl[x][y].doormask & (D_CLOSED | D_LOCKED)));
}

static void
ex_run_chains(struct ex_hit_context *ctx)
{
    unsigned c, seen[4];
    int hop, x, y, nx, ny, dx, dy, n, dmg, el;
    struct monst *m, *chosen;
    for (c = 0; c < ctx->chains; ++c) {
        x = ctx->x; y = ctx->y; seen[0] = ctx->target;
        el = ctx->chain[c].element;
        for (hop = 1; hop <= 3; ++hop) {
            int numerator = hop == 1 ? 3 : hop == 2 ? 9 : 27;
            int denominator = hop == 1 ? 4 : hop == 2 ? 16 : 64;
            chosen = 0; n = 0;
            for (dx = -1; dx <= 1; ++dx) for (dy = -1; dy <= 1; ++dy) {
                int k;
                nx = x + dx; ny = y + dy;
                if ((!dx && !dy) || !ex_chain_open(nx, ny)
                    || (dx && dy && (!ex_chain_open(x + dx, y)
                                    || !ex_chain_open(x, y + dy)))) continue;
                m = m_at(nx, ny);
                if (!m || DEADMONSTER(m) || m->mpeaceful || m->mtame) continue;
                for (k = 0; k < hop && seen[k] != m->m_id; ++k) ;
                if (k != hop) continue;
                if (!rn2(++n)) chosen = m;
            }
            if (!chosen) break;
            x = chosen->mx; y = chosen->my; seen[hop] = chosen->m_id;
            if (defended(chosen, el) || (el == AD_FIRE && resists_fire(chosen))
                || (el == AD_COLD && resists_cold(chosen))
                || (el == AD_ELEC && resists_elec(chosen))
                || (el == AD_ACID && resists_acid(chosen))) break;
            dmg = max(1, ctx->chain[c].base * numerator / denominator);
            ex_secondary_begin();
            enhancement_mon_damage(chosen, &gy.youmonst, dmg, 0);
            if (DEADMONSTER(chosen)) killed(chosen);
            ex_secondary_end();
        }
    }
}

void
ex_hit_finish(struct ex_hit_context *ctx, struct monst *mon, int actual_damage)
{
    unsigned i;
    int phase, prop, candidate, chance;
    static const int order[] = { EX_EXECUTION, EX_STEAL, EX_DISARM,
                                EX_POLYMORPH, EX_MUTE, EX_ANTIREGEN };
    struct obj *source, *wep;
    ex_cancel_element();
    if (!ctx->enabled) return;
    for (phase = 0; phase < SIZE(order); ++phase) {
        prop = order[phase];
        for (i = 0; i < ctx->sources.count && !DEADMONSTER(mon) && mon->mx; ++i) {
            source = ex_source(&ctx->sources, i, prop, &gy.youmonst);
            if (!source || ((source->exotic.striking & (1UL << prop))
                            && source->o_id != ctx->weapon)) continue;
            chance = prop == EX_MUTE ? 25 : 20;
            if (prop == EX_EXECUTION) {
                int unique = !!(mon->data->geno & G_UNIQ);
                if (actual_damage <= 0 || ex_protected_monster(mon)
                    || 100L * mon->mhp > (unique ? 15L : 25L) * mon->mhpmax) continue;
                chance = unique ? 10 : 20;
            }
            if (prop == EX_DISARM && (!(wep = MON_WEP(mon)) || wep->cursed
                                     || ex_protected_object(wep))) continue;
            if (prop == EX_POLYMORPH
                && (ex_protected_monster(mon) || (mon->data->geno & G_UNIQ))) continue;
            if (!ex_combat_chance(chance)) continue;
            switch (prop) {
            case EX_EXECUTION:
                mon->mhp = 0; /* F4: fatal, never send through DR again */
                killed(mon);
                break;
            case EX_STEAL: ex_steal(mon); break;
            case EX_DISARM:
                wep = MON_WEP(mon);
                if (wep && !wep->cursed && !ex_protected_object(wep)) mdrop_obj(mon, wep, TRUE);
                break;
            case EX_POLYMORPH:
#ifdef STEP15_TEST
                ++ex_test_poly_attempts;
#endif
                if (!resists_magm(mon) && !resist(mon, SPBOOK_CLASS, 0, NOTELL)
                    && (candidate = ex_poly_candidate(mon)) != NON_PM) {
                    int transformed = newcham(mon, &mons[candidate], NC_SHOW_MSG);
#ifdef STEP15_TEST
                    if (transformed) ++ex_test_poly_changes;
#else
                    nhUse(transformed);
#endif
                }
                break;
            case EX_MUTE: ex_apply_mute(mon); break;
            case EX_ANTIREGEN: mon->ex_regen_until = svm.moves + 5; break;
            }
        }
    }
    ex_run_chains(ctx);
}

/* Independent defensive events and their native lifecycle. */
static struct ex_melee_context *ex_incoming;
static struct monst *ex_area_caster;
static int ex_area_level;
void ex_area_spell_begin(struct monst *caster, int level)
{
    ex_area_caster = caster; ex_area_level = level;
}
void ex_area_spell_end(void) { ex_area_caster = NULL; }
int ex_area_spell_square(int x, int y)
{
    return ex_area_caster && u_at(x,y) && ex_absorb(ex_area_caster,TRUE,ex_area_level);
}
static struct ex_guardian_window *
ex_window(unsigned source, long until, int create)
{
    unsigned i;
    struct ex_guardian_window *empty = NULL;
    for (i = 0; i < EX_MAX_SOURCES; ++i) {
        struct ex_guardian_window *w = &u.ex_guardians[i];
        if (w->source == source && w->until == until) return w;
        if (!empty && (!w->source || w->until <= svm.moves)) empty = w;
    }
    if (!create || !empty) return NULL;
    empty->source = source; empty->until = until; empty->count = 0;
    return empty;
}

void
ex_guardian_detach(struct monst *m)
{
    struct ex_guardian_window *w;
    if (!m || !m->ex_guardian_until) return;
    w = ex_window(m->ex_guardian_source,m->ex_guardian_until,0);
    if (w && w->count) --w->count;
    m->ex_guardian_until = 0; m->ex_guardian_source = 0;
}
void
ex_guardian_clone(struct monst *m)
{
    struct ex_guardian_window *w;
    if (!m || !m->ex_guardian_until) return;
    w = ex_window(m->ex_guardian_source,m->ex_guardian_until,0);
    if (w) ++w->count;
}

static int ex_low_hp(void)
{
    int hp = Upolyd ? u.mh : u.uhp, maximum = Upolyd ? u.mhmax : u.uhpmax;
    return hp > 0 && maximum > 0 && (long) hp * 4 <= maximum;
}

static struct monst *ex_defender_by_id(unsigned id)
{
    struct monst *m;
    for (m = fmon; m; m = m->nmon)
        if (m->m_id == id && !DEADMONSTER(m)) return m;
    return NULL;
}

int
ex_guardian_expire(struct monst *m)
{
    if (!m || !m->ex_guardian_until || svm.moves < m->ex_guardian_until)
        return 0;
    /* Migration overloads mx/my. Death and loot need a real map square. */
    if ((m->mstate & (MON_MIGRATING | MON_LIMBO)) || !isok(m->mx, m->my)
        || (m != u.usteed && m_at(m->mx, m->my) != m))
        return 0;
    /* Unlink before native death, which may lifesave, revert, or recurse.
     * A lifesaved survivor is permanently an ordinary pet. */
    ex_guardian_detach(m);
    if (DEADMONSTER(m)) return 1;
    mondied(m);
    return DEADMONSTER(m) ? 1 : 0;
}

void ex_monster_arrived(struct monst *m) { (void) ex_guardian_expire(m); }

static void ex_guardian_group(struct obj *source)
{
    struct permonst *pm;
    struct monst *m;
    coord cc;
    int n, i, placed = 0;
    long deadline;
    if (source->exotic.guardian_until > svm.moves) return;
    n = rnd(3); deadline = svm.moves + 30;
    for (i = 0; i < n; ++i) {
        pm = rndmonst_adj(0,0);
        if (!pm || (pm->geno & G_UNIQ) || is_rider(pm)
            || !enexto(&cc,u.ux,u.uy,pm)) continue;
        m = makemon(pm,cc.x,cc.y,MM_EDOG | NO_MINVENT | MM_NOMSG);
        if (!m) continue;
        initedog(m,FALSE);
        m->ex_guardian_source = source->o_id;
        m->ex_guardian_until = deadline;
        ++placed;
    }
    if (placed) {
        struct ex_guardian_window *w = ex_window(source->o_id,deadline,1);
        if (w) w->count = placed;
        source->exotic.guardian_until = deadline;
    }
}

void
ex_melee_begin(struct ex_melee_context *e, struct monst *attacker)
{
    memset(e,0,sizeof *e);
    e->attacker = attacker->m_id;
    e->hostile = !ex_secondary() && !attacker->mpeaceful && !attacker->mtame
                 && m_next2u(attacker);
    e->before_hp = Upolyd ? u.mh : u.uhp;
    e->before_poly = !!Upolyd;
    ex_snapshot(&e->sources,&gy.youmonst);
    ex_incoming = e;
    if (!ex_low_hp()) u.ex_teleport_disarmed = FALSE;
}

void
ex_melee_damage(struct monst *attacker, int damage)
{
    if (ex_incoming && !ex_secondary() && attacker
        && attacker->m_id == ex_incoming->attacker && damage > 0)
        ex_incoming->damage += damage;
}

void
ex_melee_end(struct ex_melee_context *e)
{
    struct obj *source, *weapon;
    struct monst *attacker;
    unsigned i;
    int original_low, mortality, hp = Upolyd ? u.mh : u.uhp;
    ex_incoming = NULL;
    if (!e->hostile) return;
    if (!!Upolyd == e->before_poly && hp < e->before_hp)
        e->damage = max(e->damage,e->before_hp - hp);
    original_low = e->damage > 0 && ex_low_hp();
    if (!ex_low_hp()) u.ex_teleport_disarmed = FALSE;
    mortality = u.umortality;
    for (i = 0; i < e->sources.count; ++i) {
        if (gm.multi < 0 || (Upolyd ? u.mh : u.uhp) < 1
            || u.umortality != mortality) break;
        attacker = ex_defender_by_id(e->attacker);
        if (!attacker || !m_next2u(attacker)) break;
        source = ex_source(&e->sources,i,EX_COUNTER,&gy.youmonst);
        if (!source) continue;
        if (source == uwep || (u.twoweap && source == uswapwep)) weapon = source;
        else if (source->exotic.counter_weapon == EX_WEAPON_MAIN) weapon = uwep;
        else if (source->exotic.counter_weapon == EX_WEAPON_OFF && u.twoweap) weapon = uswapwep;
        else continue;
        if (!weapon || (weapon->oclass != WEAPON_CLASS && !is_weptool(weapon))
            || is_launcher(weapon)
            || is_ammo(weapon) || is_missile(weapon)) continue;
        if (!ex_roll(EX_COUNTER)) continue;
        ex_secondary_begin();
        (void) ex_counterattack(attacker,weapon);
        ex_secondary_end();
    }
    if (!original_low || !ex_low_hp()) return;
    for (i = 0; i < e->sources.count && ex_low_hp(); ++i) {
        source = ex_source(&e->sources,i,EX_GUARDIANS,&gy.youmonst);
        if (source) ex_guardian_group(source);
    }
    for (i = 0; i < e->sources.count && ex_low_hp()
                && !u.ex_teleport_disarmed; ++i) {
        source = ex_source(&e->sources,i,EX_TELEPORT,&gy.youmonst);
        if (source && ex_reactive_teleport()) {
            u.ex_teleport_disarmed = TRUE;
            break;
        }
    }
}

int
ex_absorb(struct monst *caster, int listed, int level)
{
    struct ex_sources sources;
    unsigned i;
    int energy;
    if (!caster || caster->mpeaceful || caster->mtame || ex_secondary()) return 0;
    ex_snapshot(&sources,&gy.youmonst);
    for (i = 0; i < sources.count; ++i) {
        if (!ex_source(&sources,i,EX_ABSORB,&gy.youmonst) || !ex_roll(EX_ABSORB)) continue;
        energy = listed ? max(1,level) * rnd(6) : d(6,6);
        u.uen = min(u.uenmax,u.uen + energy);
        disp.botl = TRUE;
        You("absorb the spell's energy.");
        return 1;
    }
    return 0;
}

void
ex_world_turn(void)
{
    struct monst *m, *next;
    if (!ex_low_hp()) u.ex_teleport_disarmed = FALSE;
    for (m = fmon; m; m = next) {
        next = m->nmon;
        (void) ex_guardian_expire(m);
    }
}

void ex_health_changed(void)
{
    if (!ex_low_hp()) u.ex_teleport_disarmed = FALSE;
}

void
ex_inspect(struct obj *o, int win)
{
    static const char *const names[EX_COUNT] = {
        "Disarming (20%)", "Enhanced Steal (20%)", "Polymorphic Strike (20%)",
        "Anti-Regeneration (20%, 5 turns)", "Frenzy (20%, 1-3 ticks)",
        "Executioner (20% ordinary, 10% eligible unique)", "Elemental Chain (30%, 3 hops)",
        "Counterstrike (33%)", "Reactive Teleportation", "Emergency Summoning (30 turns)",
        "Spell Absorption (20%)", "Universal Trap Disarming", "Wall Consumption",
        "Corpse Preservation", "Consumable Conservation (30/20/10%)",
        "Environmental Transmutation", "Anti-Theft Ward (100%)", "Ability Mute (25%, 2d3 turns)"
    };
    static const char *const modes[] = {
        "inactive", "directly carried", "carried, including containers",
        "wielded", "worn in the assigned slot", "manual activation", "invoked"
    };
    int p, k, count;
    long remaining, charge;
    char buf[BUFSZ];
    ex_preserve_inspect(o,win);
    if (!o->oartifact || !o->known || !o->dknown
        || undiscovered_artifact(o->oartifact)) return;
    for (p = 0; p < EX_COUNT; ++p) {
        if (!(o->exotic.grants & (1UL << p))) continue;
        Snprintf(buf,sizeof buf,"%s: %s (%s).",names[p],
                 modes[min(o->exotic.activation[p],EX_INVOKED)],
                 ex_active(o,p,&gy.youmonst) ? "active" : "inactive");
        putstr(win,ATR_NONE,buf);
        if (p == EX_TELEPORT)
            putstr(win,ATR_NONE,u.ex_teleport_disarmed
                   ? "Disarmed: rearm when active HP rises above 25%."
                   : "Armed: rearm after success when active HP rises above 25%.");
        if (p == EX_GUARDIANS) {
            struct ex_guardian_window *w = ex_window(o->o_id,o->exotic.guardian_until,0);
            count = w && w->until > svm.moves ? w->count : 0;
            remaining = max(0L,o->exotic.guardian_until - svm.moves);
            Snprintf(buf,sizeof buf,"%s: %d linked guardians, %ld turns remaining.",
                     !remaining ? "Ready" : count ? "Active" : "Recovering",count,remaining);
            putstr(win,ATR_NONE,buf);
        }
        if (p == EX_DIG || p == EX_TRANSMUTE) {
            struct obj copy = *o; /* inspection cannot mutate saved charge state */
            k = p == EX_DIG ? 0 : 1; ex_resources(&copy);
            charge = k ? 10 : 100;
            remaining = copy.exotic.charges[k] == (k ? 10 : 5) ? 0
                : charge - (svm.moves-copy.exotic.charge_turn[k]);
            Snprintf(buf,sizeof buf,"Charges: %u/%d, next recharge in %ld turns.",
                     copy.exotic.charges[k],k ? 10 : 5,remaining);
            putstr(win,ATR_NONE,buf);
        }
    }
}

int
ex_invoke(struct obj *o, int native)
{
    int props[2] = {EX_DIG,EX_TRANSMUTE}, selected = -1, n = 0, p, result;
    anything any;
    winid win;
    menu_item *items = NULL;
    for (p = 0; p < 2; ++p) if (ex_active(o,props[p],&gy.youmonst)) {selected = props[p]; ++n;}
    if (!n) return -1;
    if (n > 1 || native) {
        win = create_nhwindow(NHW_MENU); start_menu(win,MENU_BEHAVE_STANDARD);
        for (p = 0; p < 2; ++p) {
            if (!ex_active(o,props[p],&gy.youmonst)) continue;
            any = cg.zeroany; any.a_int = props[p]+1;
            add_menu(win,&nul_glyphinfo,&any,0,0,ATR_NONE,NO_COLOR,
                     p ? "Environmental Transmutation" : "Wall Consumption",MENU_ITEMFLAGS_NONE);
        }
        if (native) {
            any = cg.zeroany; any.a_int = EX_COUNT+1;
            add_menu(win,&nul_glyphinfo,&any,0,0,ATR_NONE,NO_COLOR,
                     "Existing invocation",MENU_ITEMFLAGS_NONE);
        }
        end_menu(win,"Invoke which ability?");
        result = select_menu(win,PICK_ONE,&items); destroy_nhwindow(win);
        if (result < 1) {if (items) free(items); return 0;}
        selected = items[0].item.a_int-1; free(items);
        if (selected == EX_COUNT) return -1;
    }
    return ex_utility_invoke(o,selected);
}
